package com.votesecure.onlinevoting.controller;
import com.votesecure.onlinevoting.model.*;import com.votesecure.onlinevoting.repository.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class PublicController{private final ElectionRepository er;private final CandidateRepository cr;private final VoteRepository vr;public PublicController(ElectionRepository e,CandidateRepository c,VoteRepository v){er=e;cr=c;vr=v;}@GetMapping("/election") public Object election(){return er.findAll().stream().findFirst().orElse(null);}@GetMapping("/candidates") public Object candidates(){return cr.findByActiveTrue();}@GetMapping("/results") public Object results(){List<Map<String,Object>> out=new ArrayList<>();for(Object[] x:vr.counts())out.add(Map.of("candidateId",x[0],"candidateName",x[1],"partyName",x[2],"voteCount",x[3]));return out;}@GetMapping("/health") public Object health(){return Map.of("status","UP");}}
